interface Shape { <R> R accept(ShapeVisitor<R> v); }

abstract class ShapeVisitor<R> {
    public abstract R visit(Circle c);
    public abstract R visit(Rect r);
}

final class Circle implements Shape {
    final double r; Circle(double r) { this.r = r; }
    public <R> R accept(ShapeVisitor<R> v) { return v.visit(this); }   // 2nd dispatch
}
var area = shape.accept(new AreaVisitor());

sealed interface Shape permits Circle, Rect, Triangle {}
record Circle(double r) implements Shape {}
record Rect(double w, double h) implements Shape {}

static double area(Shape s) {
    return switch (s) {                       // no default: coverage is proven
        case Circle c -> Math.PI * c.r() * c.r();
        case Rect r   -> r.w() * r.h();
        case Triangle t -> 0.5 * t.base() * t.height();
    };
}
